library(shiny)

merchantUI<-function(id){ns<-NS(id);tagList(tags$style(HTML(paste0("#",ns("wrap"),"{position:fixed;right:22px;bottom:94px;z-index:1039}#",ns("open"),"{width:58px;height:58px;border-radius:50%;font-size:24px;background:#31543b;color:#fff4cf;border:2px solid #d7b96d;box-shadow:0 5px 18px rgba(0,0,0,.35)}#",ns("badge"),"{position:absolute;right:-3px;top:-5px;background:#8f241d;color:white;border-radius:999px;min-width:22px;padding:2px 6px;text-align:center;font-weight:bold}"))),div(id=ns("wrap"),actionButton(ns("open"),"⚖",title="Merchants"),uiOutput(ns("badge"))))}

merchantServer<-function(id,state){moduleServer(id,function(input,output,session){`%||%`<-get("%||%",inherits=TRUE);poll<-reactiveTimer(3000,session);rev<-reactiveVal(0L);prompted<-reactiveVal(integer());active_id<-reactiveVal(NA_integer_);active_quote<-reactiveVal(NULL)
  cid<-reactive({x<-state$char_id;if(is.null(x)||!length(x)||is.na(x[[1]]))""else as.character(x[[1]])})
  invitations<-reactive({poll();rev();if(!nzchar(cid())||isTRUE(state$offline_mode))return(data.frame());get_pending_merchant_invitations(cid(),FALSE)})
  output$badge<-renderUI({n<-sum(invitations()$status=="pending");if(n>0)span(n)})
  merchant_choices<-function(){x<-invitations();if(!nrow(x))character()else setNames(as.character(x$merchant_id),paste0(x$name," · ",tools::toTitleCase(x$specialty)))}
  close_stale_shop<-function(message="That merchant has closed and is no longer trading."){active_quote(NULL);active_id(NA_integer_);session$userData$pending_merchant_id<-NULL;removeModal();rev(rev()+1L);showNotification(message,type="warning",duration=8)}
  open_shop<-function(mid){mid<-suppressWarnings(as.integer(mid));bundle<-get_merchant_bundle(mid);if(is.null(bundle)||!identical(as.character(bundle$merchant$status[[1L]]),"open"))return(close_stale_shop());active_id(mid);mark_merchant_invitation(mid,cid(),"opened");session$userData$pending_merchant_id<-mid;rev(rev()+1L);showModal(modalDialog(size="l",title=paste0(bundle$merchant$name[[1L]]," — ",tools::toTitleCase(bundle$merchant$specialty[[1L]])," merchant"),uiOutput(session$ns("shop_body")),footer=tagList(actionButton(session$ns("leave_shop"),"Leave merchant",class="btn btn-default"))))}
  item_detail_lines<-function(item){
    m<-item$meta%||%list();type<-tolower(as.character(item$type%||%"item"));category<-tolower(as.character(m$category%||%""));lines<-character()
    if(type=="weapon")lines<-c(lines,paste0("Damage ",m$damage1%||%"1d4"," ",m$dmg_type1%||%"other",if(nzchar(as.character(m$damage2%||%"")))paste0(" + ",m$damage2," ",m$dmg_type2%||%"other")else""," · ",toupper(m$stat%||%"str")))
    if(type%in%c("armor","armour")){slot<-m$equipment_slot%||%if(identical(m$type,"Shield"))"shield"else"body";lines<-c(lines,if(slot=="body")paste0(m$type%||%"Armour"," · Base AC ",m$base_ac%||%"—")else paste0(tools::toTitleCase(slot)," · +",m$ac_bonus%||%0," AC"))}
    if(type=="animal")lines<-c(lines,paste0(m$species%||%"Animal"," · Speed ",m$speed%||%30," ft · AC ",m$armour_class%||%10," · HP ",m$max_hp%||%5," · ",if(isTRUE(m$mountable))"Mountable"else"Unmountable"))
    if(category=="food")lines<-c(lines,paste0(m$ration_value%||%1," ration(s) · fresh for ",m$shelf_life_days%||%3," day(s)"))
    if(nzchar(as.character(m$effect%||%"")))lines<-c(lines,paste0("Effect: ",gsub("_"," ",m$effect),if(nzchar(as.character(m$effect_amount%||%"")))paste0(" ",m$effect_amount)else""))
    if(length(m$resistances%||%character()))lines<-c(lines,paste0("Resistance: ",paste(m$resistances,collapse=", ")))
    if(length(m$condition_immunities%||%character()))lines<-c(lines,paste0("Condition immunity: ",paste(m$condition_immunities,collapse=", ")))
    provenance<-paste(na.omit(c(as.character(m$material%||%NA),as.character(m$build_quality%||%NA))),collapse=" · ");if(nzchar(provenance))lines<-c(lines,provenance)
    lines
  }
  stock_card<-function(stock_row){item<-enemy_db_json(stock_row$item_json[[1L]],list());lines<-item_detail_lines(item);tags$div(class="merchant-stock-card",tags$div(class="merchant-stock-head",tags$div(tags$div(class="merchant-stock-name",item$name%||%"Item"),tags$div(class="merchant-stock-meta",paste0(tools::toTitleCase(gsub("_"," ",as.character((item$meta%||%list())$category%||%item$type%||%"item")))," · ",stock_row$base_value[[1L]],"g base · ",stock_row$quantity[[1L]]," available"))),tags$button(type="button",class="btn btn-success",onclick=sprintf("Shiny.setInputValue('%s', %d, {priority: 'event'})",session$ns("buy_card"),as.integer(stock_row$id[[1L]])),"Haggle to Buy")),if(nzchar(as.character(item$desc%||%"")))tags$p(class="merchant-stock-desc",item$desc),if(length(lines))tags$div(class="merchant-stock-stats",lapply(lines,function(x)tags$span(x))))}
  output$shop_body<-renderUI({
    rev();mid<-active_id();if(is.na(mid))return(NULL);b<-get_merchant_bundle(mid);if(is.null(b))return(p("Merchant closed."));m<-b$merchant;s<-b$stock;char<-validate_character(state$char);inv<-inventory_normalize(char$inventory$items);if(nrow(inv))inv<-inv[!as.logical(inv$equipped%||%FALSE),,drop=FALSE];sell_choices<-if(nrow(inv))setNames(inv$id,paste0(inv$name," · ",inv$value,"g base · qty ",inv$qty))else character()
    tagList(tags$style(HTML(".merchant-stock-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:12px;max-height:58vh;overflow-y:auto;padding:3px}.merchant-stock-card{border:1px solid #b99a5d;border-radius:12px;background:#fffdf5;padding:12px}.merchant-stock-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.merchant-stock-name{font-size:17px;font-weight:700}.merchant-stock-meta{font-size:12px;color:#715d39;margin-top:3px}.merchant-stock-desc{margin:10px 0;white-space:pre-wrap}.merchant-stock-stats{display:flex;flex-wrap:wrap;gap:5px}.merchant-stock-stats span{background:#eee4ca;border-radius:999px;padding:4px 8px;font-size:12px}")),p(strong(tools::toTitleCase(m$temperament[[1L]]))," haggler · Merchant purse: ",m$gold[[1L]],"g · Your purse: ",char$inventory$gold%||%0,"g"),p("Every ware is shown below. Haggle from its card; nothing changes hands until you accept the quote."),h4("Wares"),if(nrow(s))div(class="merchant-stock-grid",lapply(seq_len(nrow(s)),function(i)stock_card(s[i,,drop=FALSE])))else tags$em("Sold out."),tags$hr(),h4("Sell to Merchant"),selectInput(session$ns("sell_item"),"Your unequipped item or stable animal",choices=sell_choices),actionButton(session$ns("sell"),"Haggle Sale",class="btn btn-primary"))
  })
  observe({rev();if(is.na(active_id()))return();char<-validate_character(state$char);inv<-inventory_normalize(char$inventory$items);if(nrow(inv))inv<-inv[!as.logical(inv$equipped%||%FALSE),,drop=FALSE];item_choices<-if(nrow(inv))setNames(inv$id,paste0(inv$name," · ",inv$value,"g base · qty ",inv$qty))else character();stable<-get_character_stable(cid());animal_choices<-if(nrow(stable))setNames(paste0("animal:",stable$id),paste0("🐾 ",stable$name," · ",stable$gold_value,"g base · ",ifelse(stable$mountable,"Mountable","Unmountable")))else character();updateSelectInput(session,"sell_item",choices=c(item_choices,animal_choices))})
  negotiate<-function(direction,target=NULL){mid<-active_id();if(is.null(target))target<-if(direction=="buy")input$buy_stock else input$sell_item;if(is.na(mid)||is.null(target)||!nzchar(as.character(target)))return(showNotification("Choose an item first.",type="warning"));q<-create_merchant_quote(mid,cid(),direction,stock_id=if(direction=="buy")target else NULL,player_item_id=if(direction=="sell")target else NULL);if(merchant_action_failed(q)){msg<-merchant_error_message(q,"The merchant could not make a quote.");if(grepl("no longer open",msg,fixed=TRUE))return(close_stale_shop());return(showNotification(msg,type="error",duration=8))};active_quote(q);char_gold<-as.numeric(validate_character(state$char)$inventory$gold%||%0);bundle<-get_merchant_bundle(mid);if(is.null(bundle)||!identical(as.character(bundle$merchant$status[[1L]]),"open"))return(close_stale_shop());merchant_gold<-as.numeric(bundle$merchant$gold[[1L]]);can_afford<-if(direction=="buy")char_gold>=as.numeric(q$final_price[[1L]])else merchant_gold>=as.numeric(q$final_price[[1L]]);if(direction=="buy"&&as.integer(q$natural_roll[[1L]]%||%NA)==1L){if(!can_afford)return(showModal(modalDialog(title="Critical haggling failure",p("You rolled a natural 1. The merchant doubled the price to ",strong(paste0(q$final_price[[1L]]," gold"))," and tried to make the sale automatic, but you only have ",char_gold," gold. Nothing was bought."),footer=actionButton(session$ns("reject_quote"),"Leave Quote",class="btn btn-default"))));res<-merchant_trade(mid,cid(),quote_id=q$id[[1L]]);if(merchant_action_failed(res)){msg<-merchant_error_message(res);if(grepl("no longer open",msg,fixed=TRUE))return(close_stale_shop());return(showNotification(msg,type="error",duration=8))};state$char<-res$character;active_quote(NULL);rev(rev()+1L);showModal(modalDialog(title="Critical haggling failure — automatic purchase",p("You rolled a natural 1 on Persuasion. The merchant doubled the base price and the purchase was automatically approved."),p(strong(res$item_name)," cost ",strong(paste0(res$terms$price," gold")),if(isTRUE(res$is_animal))" and is now in your Stables."else" and has been added to your inventory."),footer=actionButton(session$ns("return_to_shop"),"Return to Merchant",class="btn btn-primary")));return()};showModal(modalDialog(title=if(direction=="buy")"Purchase quote"else"Sale quote",p(if(isTRUE(q$haggle_success[[1L]]))"Your haggling succeeded."else"The merchant held firm."),p(strong(q$item_name[[1L]])," · Roll ",q$haggle_roll[[1L]]," vs DC ",q$haggle_dc[[1L]]," · Quoted price: ",strong(paste0(q$final_price[[1L]]," gold"))),if(!can_afford)p(style="color:#9b241c;font-weight:bold",if(direction=="buy")paste0("You only have ",char_gold," gold.")else paste0("The merchant only has ",merchant_gold," gold.")),p("Declining makes the next attempt with this merchant harder."),footer=tagList(actionButton(session$ns("reject_quote"),"Decline Quote",class="btn btn-default"),actionButton(session$ns("accept_quote"),if(direction=="buy")"Confirm Purchase"else"Confirm Sale",class="btn btn-success",disabled=if(!can_afford)"disabled"else NULL))))}
  observeEvent(input$buy_card,negotiate("buy",input$buy_card),ignoreInit=TRUE);observeEvent(input$sell,negotiate("sell"),ignoreInit=TRUE)
  observeEvent(input$reject_quote,{q<-active_quote();if(!is.null(q))reject_merchant_quote(q$id[[1L]],cid());active_quote(NULL);removeModal();open_shop(active_id())},ignoreInit=TRUE)
  observeEvent(input$accept_quote,{q<-active_quote();if(is.null(q))return();res<-merchant_trade(active_id(),cid(),quote_id=q$id[[1L]]);if(merchant_action_failed(res)){msg<-merchant_error_message(res,"The trade could not be completed.");if(grepl("no longer open",msg,fixed=TRUE))return(close_stale_shop());return(showNotification(msg,type="error",duration=8))};state$char<-res$character;active_quote(NULL);rev(rev()+1L);removeModal();t<-res$terms;destination<-if(isTRUE(res$is_animal))" It is now in your Stables."else"";showNotification(paste0(if(res$direction=="buy")"Purchased "else"Sold ",res$item_name," for ",t$price," gold.",destination),type="message",duration=8);open_shop(active_id())},ignoreInit=TRUE)
  observeEvent(input$return_to_shop,{removeModal();open_shop(active_id())},ignoreInit=TRUE)
  observeEvent(input$leave_shop,{session$userData$pending_merchant_id<-NULL;removeModal()},ignoreInit=TRUE)
  observeEvent(input$open,{choices<-merchant_choices();if(!length(choices))return(showNotification("No merchant is currently trading with you.",type="message"));if(length(choices)==1)return(open_shop(unname(choices[[1L]])));showModal(modalDialog(title="Available merchants",selectInput(session$ns("merchant_choice"),"Merchant",choices=choices),footer=tagList(modalButton("Cancel"),actionButton(session$ns("choose_merchant"),"Visit",class="btn btn-success"))))},ignoreInit=TRUE)
  observeEvent(input$choose_merchant,{removeModal();open_shop(input$merchant_choice)},ignoreInit=TRUE)
  observe({invalidateLater(3000,session);if(!nzchar(cid())||isTRUE(state$offline_mode)||!is.null(session$userData$pending_merchant_id)||!is.null(session$userData$pending_trade_id)||!is.null(session$userData$pending_note_id)||!is.null(session$userData$pending_opportunity))return();fresh<-get_pending_merchant_invitations(cid(),TRUE);fresh<-fresh[!fresh$merchant_id%in%prompted(),,drop=FALSE];if(!nrow(fresh))return();r<-fresh[1,,drop=FALSE];prompted(unique(c(prompted(),r$merchant_id)));session$userData$pending_merchant_id<-as.integer(r$merchant_id[[1L]]);showModal(modalDialog(title=paste0(r$name[[1L]]," would like to trade"),p("A ",r$wealth_class[[1L]]," ",r$specialty[[1L]]," merchant with a ",r$temperament[[1L]]," haggling style has opened their wares."),footer=tagList(actionButton(session$ns("dismiss_invite"),"Not now"),actionButton(session$ns("accept_invite"),"View wares",class="btn btn-success"))))})
  observeEvent(input$accept_invite,{mid<-session$userData$pending_merchant_id;removeModal();open_shop(mid)},ignoreInit=TRUE)
  observeEvent(input$dismiss_invite,{session$userData$pending_merchant_id<-NULL;removeModal();rev(rev()+1L)},ignoreInit=TRUE)
})}
